import { Bot, Code2, Globe, Layers, Mail, Server } from "lucide-react"
import type { Metadata } from "next"
import type { ReactNode } from "react"

import { FeatureColumns } from "@/registry/blocks/feature-columns/feature-columns"
import { ProfileHero } from "@/registry/blocks/profile-hero/profile-hero"
import {
  GitHubMark,
  XMark,
} from "@/registry/blocks/social-follow/brand-icons"
import { SocialFollow } from "@/registry/blocks/social-follow/social-follow"
import { AboutSection } from "@/registry/templates/portfolio-grid/components/portfolio/about-section"
import { SiteFooter } from "@/registry/templates/portfolio-grid/components/portfolio/site-footer"
import { SiteHeader } from "@/registry/templates/portfolio-grid/components/portfolio/site-header"
import { StackSection } from "@/registry/templates/portfolio-grid/components/portfolio/stack-section"
import {
  siteConfig,
  type FocusIcon,
  type SocialIcon,
} from "@/registry/templates/portfolio-grid/lib/site.config"
import {
  GridContainer,
  GridSeparator,
} from "@/registry/ui/grid-layout/grid-layout"

export const metadata: Metadata = {
  title: siteConfig.name,
  description: siteConfig.bio,
}

const socialIcons: Record<SocialIcon, ReactNode> = {
  github: <GitHubMark />,
  x: <XMark />,
  mail: <Mail strokeWidth={1.5} />,
  link: <Globe strokeWidth={1.5} />,
}
const focusIcons: Record<FocusIcon, ReactNode> = {
  code: <Code2 strokeWidth={1.5} />,
  bot: <Bot strokeWidth={1.5} />,
  server: <Server strokeWidth={1.5} />,
  layout: <Layers strokeWidth={1.5} />,
}

/** 线条网格个人主页：所有内容来自 lib/site.config.ts，一般只需要改那个文件。 */
export default function Page() {
  return (
    <>
      <SiteHeader />
      <main data-slot="portfolio-grid">
        <GridContainer>
          <ProfileHero
            name={siteConfig.name}
            bio={siteConfig.bio}
            roles={siteConfig.roles}
            initials={siteConfig.initials}
            tagline={siteConfig.tagline}
          />
          <SocialFollow
            followMe={false}
            socials={siteConfig.socials.map((social) => ({
              name: social.name,
              href: social.href,
              icon: socialIcons[social.icon],
            }))}
          />
          <FeatureColumns
            title={siteConfig.focus.title}
            items={siteConfig.focus.items.map((item) => ({
              title: item.title,
              description: item.description,
              icon: focusIcons[item.icon],
            }))}
            id="focus"
            className="scroll-mt-16"
          />
          <StackSection
            title={siteConfig.stack.title}
            items={siteConfig.stack.items}
          />
          <GridSeparator />
          <AboutSection
            title={siteConfig.about.title}
            paragraphs={siteConfig.about.paragraphs}
          />
        </GridContainer>
      </main>
      <SiteFooter />
    </>
  )
}

/**
 * 个人主页的全部内容都集中在这个文件：改完保存，整页同步更新。
 * 颜色请通过主题变量（globals.css）调整，不要在组件里硬编码。
 */

/** 社交链接支持的图标：github / x / mail / link */
type SocialIcon = "github" | "x" | "mail" | "link"
/** 「我在做什么」支持的图标：code / bot / server / layout */
type FocusIcon = "code" | "bot" | "server" | "layout"

const siteConfig = {
  name: "Your Name",
  /** 头像方块里显示的缩写，1–2 个字符 */
  initials: "Y",
  /** 横幅中间的装饰文字，设为空字符串可隐藏 */
  tagline: "DESIGN · CODE · REPEAT",
  bio: "全栈开发者，专注 AI 应用与产品体验。从界面到服务，把想法做成可用的东西。",
  /** 职业标签，在封面区依次轮播 */
  roles: ["全栈开发", "AI 应用", "界面设计"],
  /** 页头的锚点导航，href 对应各区块的 id */
  nav: [
    { label: "做什么", href: "#focus" },
    { label: "技术栈", href: "#stack" },
    { label: "关于", href: "#about" },
  ],
  socials: [
    { name: "GitHub", icon: "github", href: "https://github.com/your-name" },
    { name: "X", icon: "x", href: "https://x.com/your-name" },
    { name: "邮件", icon: "mail", href: "mailto:hi@example.com" },
  ] satisfies { name: string; icon: SocialIcon; href: string }[],
  focus: {
    title: "我在做什么",
    items: [
      {
        title: "全栈开发",
        icon: "code",
        description: "从前端界面到后端服务，构建完整、可靠的产品体验。",
      },
      {
        title: "AI 应用与 Agent",
        icon: "bot",
        description: "连接模型、工具与业务流程，让 AI 进入真实的工作场景。",
      },
      {
        title: "界面系统",
        icon: "layout",
        description: "把反复用到的界面细节整理成可复制的组件。",
      },
    ] satisfies { title: string; icon: FocusIcon; description: string }[],
  },
  stack: {
    title: "技术栈",
    items: [
      "TypeScript",
      "React",
      "Next.js",
      "Node.js",
      "Tailwind CSS",
      "PostgreSQL",
      "Docker",
      "Python",
    ],
  },
  about: {
    title: "关于我",
    paragraphs: [
      "你好，我是 Your Name。这里是我的个人主页，记录作品，也记录那些值得反复打磨的小想法。",
      "相信好用的工具来自清晰的结构和耐心的打磨。持续学习，慢慢构建。",
    ],
  },
  /** 页脚的版权年份；写成固定文本，兼容 Next.js 的 Cache Components */
  year: "2026",
  footer: "用线条网格搭建",
}

type SiteConfig = typeof siteConfig

export { siteConfig }
export type { FocusIcon, SiteConfig, SocialIcon }

/**
 * 个人主页里固定的界面文案。
 * 姓名、简介、区块标题、技术栈列表等个人信息都在 site.config.ts 里。
 */
const DEFAULT_LABELS = {
  siteNav: "页面导航",
  stackEyebrow: "TOOLS OF THE TRADE",
  aboutFootnote: "持续学习，慢慢构建。",
} as const

type PortfolioGridLabels = { [Key in keyof typeof DEFAULT_LABELS]: string }

/** 合并用户传入的文案与默认文案。 */
function resolveLabels(
  labels?: Partial<PortfolioGridLabels>,
): PortfolioGridLabels {
  return { ...DEFAULT_LABELS, ...labels }
}

export { DEFAULT_LABELS, resolveLabels }
export type { PortfolioGridLabels }

import { siteConfig } from "@/registry/templates/portfolio-grid/lib/site.config"
import { GridContainer } from "@/registry/ui/grid-layout/grid-layout"

import { resolveLabels, type PortfolioGridLabels } from "../../lib/config"

/** 简易页头：站名 + 锚点导航。screen-line-bottom 放在内层，避免与 sticky 冲突。 */
function SiteHeader({
  labels,
}: {
  /** 覆盖默认文案，见 lib/config.ts 的 DEFAULT_LABELS */
  labels?: Partial<PortfolioGridLabels>
}) {
  const text = resolveLabels(labels)
  return (
    <header
      data-slot="portfolio-grid-site-header"
      className="sticky top-0 z-40 w-full bg-background/80 backdrop-blur-md supports-[backdrop-filter]:bg-background/60"
    >
      <div className="screen-line-bottom">
        <GridContainer className="flex h-14 items-center justify-between gap-4 px-4 sm:px-6">
          <a
            href="#top"
            className="rounded-md font-mono text-sm font-semibold tracking-tight outline-none focus-visible:ring-3 focus-visible:ring-ring/50"
            translate="no"
          >
            {siteConfig.name}
          </a>
          <nav
            data-slot="portfolio-grid-site-nav"
            aria-label={text.siteNav}
            className="flex items-center gap-1"
          >
            {siteConfig.nav.map((item) => (
              <a
                key={item.href}
                href={item.href}
                className="rounded-md px-2.5 py-1.5 text-sm text-muted-foreground transition-colors hover:text-foreground focus-visible:outline-2 focus-visible:outline-ring"
              >
                {item.label}
              </a>
            ))}
          </nav>
        </GridContainer>
      </div>
    </header>
  )
}

export { SiteHeader }

import { siteConfig } from "@/registry/templates/portfolio-grid/lib/site.config"
import { GridContainer } from "@/registry/ui/grid-layout/grid-layout"

/** 简易页脚：版权 + 一行说明。上方横线由页面最后一个 GridSection 提供。 */
function SiteFooter() {
  return (
    <footer data-slot="portfolio-grid-site-footer">
      <GridContainer className="flex flex-wrap items-center justify-between gap-2 px-4 py-6 font-mono text-xs text-muted-foreground sm:px-6">
        <span translate="no">
          © {siteConfig.year} {siteConfig.name}
        </span>
        <span>{siteConfig.footer}</span>
      </GridContainer>
    </footer>
  )
}

export { SiteFooter }

import { GridSection } from "@/registry/ui/grid-layout/grid-layout"

import { resolveLabels, type PortfolioGridLabels } from "../../lib/config"

/** 技术栈：两列（≥sm 四列）的小方块网格。 */
function StackSection({
  title,
  items,
  labels,
}: {
  title: string
  items: readonly string[]
  /** 覆盖默认文案，见 lib/config.ts 的 DEFAULT_LABELS */
  labels?: Partial<PortfolioGridLabels>
}) {
  const text = resolveLabels(labels)
  return (
    <GridSection
      data-slot="portfolio-grid-stack"
      id="stack"
      aria-labelledby="stack-title"
      className="scroll-mt-16 px-4 py-6 sm:px-6"
    >
      <div className="mb-5 flex items-center justify-between gap-3">
        <h2 id="stack-title" className="text-sm font-medium">
          {title}
        </h2>
        <span
          aria-hidden="true"
          className="font-mono text-[10px] text-muted-foreground"
        >
          {text.stackEyebrow}
        </span>
      </div>
      <ul className="grid grid-cols-2 gap-2 sm:grid-cols-4">
        {items.map((item) => (
          <li
            key={item}
            className="flex min-h-14 min-w-0 items-center gap-2 rounded-md border border-edge bg-muted/20 px-2.5 py-3 sm:px-3"
          >
            <span
              aria-hidden="true"
              className="flex size-6 shrink-0 items-center justify-center rounded border border-edge bg-background font-mono text-[10px] text-muted-foreground"
            >
              {item.slice(0, 2)}
            </span>
            <span
              className="min-w-0 font-mono text-[10px] break-words sm:text-xs"
              translate="no"
            >
              {item}
            </span>
          </li>
        ))}
      </ul>
    </GridSection>
  )
}

export { StackSection }

import { GridSection } from "@/registry/ui/grid-layout/grid-layout"

import { resolveLabels, type PortfolioGridLabels } from "../../lib/config"

/** 关于我：几段正文 + 一行等宽小字收尾。 */
function AboutSection({
  title,
  paragraphs,
  labels,
}: {
  title: string
  paragraphs: readonly string[]
  /** 覆盖默认文案，见 lib/config.ts 的 DEFAULT_LABELS */
  labels?: Partial<PortfolioGridLabels>
}) {
  const text = resolveLabels(labels)
  return (
    <GridSection
      data-slot="portfolio-grid-about"
      id="about"
      aria-labelledby="about-title"
      className="scroll-mt-16 px-4 py-8 sm:px-6"
    >
      <div className="mb-4 flex items-center justify-between">
        <h2 id="about-title" className="text-sm font-medium">
          {title}
        </h2>
        <span aria-hidden="true" className="text-muted-foreground">
          ↘
        </span>
      </div>
      <div className="flex max-w-xl flex-col gap-3 text-sm leading-7 text-pretty text-muted-foreground">
        {paragraphs.map((paragraph) => (
          <p key={paragraph}>{paragraph}</p>
        ))}
      </div>
      <p className="mt-6 font-mono text-xs text-muted-foreground">
        {text.aboutFootnote}
        <span className="ml-2 text-primary">_</span>
      </p>
    </GridSection>
  )
}

export { AboutSection }
